# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EVİMİN BÖLÜMLERİ (أَقْسَامُ الْبَيْتِ) VE ODALAR</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Yaşam ve Dinlenme Odaları</text>\n  <text x="125" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">غُرْفَةُ الْجُلُوسِ</text>\n  <text x="125" y="120" text-anchor="middle" font-size="11" fill="#334155">Oturma odası</text>\n  <text x="125" y="148" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">غُرْفَةُ النَّوْمِ</text>\n  <text x="125" y="166" text-anchor="middle" font-size="11" fill="#334155">Yatak odası</text>\n  <text x="125" y="194" text-anchor="middle" font-size="13" font-weight="bold" fill="#1e3a8a">غُرْفَةُ الْأَطْفَالِ / الدِّرَاسَةِ</text>\n  <text x="125" y="212" text-anchor="middle" font-size="11" fill="#334155">Çocuk odası / Çalışma odası</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Ortak Kullanım Alanları</text>\n  <text x="350" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">اَلْمَطْبَخُ (El-matbahu)</text>\n  <text x="350" y="120" text-anchor="middle" font-size="11" fill="#334155">Mutfak</text>\n  <text x="350" y="148" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">اَلْحَمَّامُ (El-hammâmu)</text>\n  <text x="350" y="166" text-anchor="middle" font-size="11" fill="#334155">Banyo</text>\n  <text x="350" y="194" text-anchor="middle" font-size="13" font-weight="bold" fill="#14532d">اَلْمِغْسَلَةُ / دَوْرَةُ الْمِيَاهِ</text>\n  <text x="350" y="212" text-anchor="middle" font-size="11" fill="#334155">Lavabo / Tuvalet</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Dış Bölümler ve Katlar</text>\n  <text x="575" y="102" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">اَلْحَدِيقَةُ (El-hadîkatü)</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#334155">Bahçe</text>\n  <text x="575" y="148" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">اَلشُّرْفَةُ (Eş-şurfetü)</text>\n  <text x="575" y="166" text-anchor="middle" font-size="11" fill="#334155">Balkon</text>\n  <text x="575" y="194" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">اَلطَّابِقُ الْأَوَّلُ / الثَّانِي</text>\n  <text x="575" y="212" text-anchor="middle" font-size="11" fill="#334155">Birinci kat / İkinci kat</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">EV EŞYALARI (اَلْأَثَاثُ) VE BULUNMA KALIPLARI (يُوجَدُ / تُوجَدُ)</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">Temel Ev Eşyaları</text>\n  <text x="180" y="100" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">أَرِيكَةٌ (Kanepe) · سَجَّادَةٌ (Halı) · سِتَارَةٌ (Perde)</text>\n  <text x="180" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">سَرِيرٌ (Yatak) · خِزَانَةٌ (Dolap) · مِرْآةٌ (Ayna)</text>\n  <text x="180" y="156" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">طَاوِلَةٌ (Masa) · كُرْسِيٌّ (Sandalye) · مَكْتَبَةٌ (Kitaplık)</text>\n  <text x="180" y="184" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">ثَلَّاجَةٌ (Buzdolabı) · فُرْنٌ (Fırın) · غَسَّالَةٌ (Çamaşır mak.)</text>\n  <text x="180" y="212" text-anchor="middle" font-size="12" font-weight="bold" fill="#6b21a8">حَاسُوبٌ (Bilgisayar) · تِلْفَازٌ (Televizyon) · سَاعَةٌ (Saat)</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">«مَاذَا يُوجَدُ فِي ...؟» (...de ne var?)</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">Eril Eşya İçin: يُوجَدُ (Yûcedü - Vardır)</text>\n  <text x="520" y="122" text-anchor="middle" font-size="12" fill="#475569">يُوجَدُ سَرِيرٌ فِي غُرْفَةِ النَّوْمِ. (Yatak odasında yatak var.)</text>\n  <text x="520" y="154" text-anchor="middle" font-size="12" font-weight="bold" fill="#9f1239">Dişil Eşya İçin: تُوجَدُ (Tûcedü - Vardır)</text>\n  <text x="520" y="174" text-anchor="middle" font-size="12" fill="#475569">تُوجَدُ ثَلَّاجَةٌ فِي الْمَطْبَخِ. (Mutfakta buzdolabı var.)</text>\n  <text x="520" y="208" text-anchor="middle" font-size="11" font-weight="bold" fill="#be123c">Sonunda «ة» bulunan eşyalarda تُوجَدُ tercih edilir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">HARF-İ CERLER, YER ZARFLARI VE «أَيْنَ ...؟» SORU KALIBI</text>\n  <rect x="25" y="48" width="310" height="190" rx="8" fill="#ecfeff" stroke="#06b6d4" stroke-width="1.5"/>\n  <text x="180" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#0e7490">Harf-i Cerler ve Yer Zarfları</text>\n  <text x="180" y="100" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">فِي : İçinde (-de/-da) · عَلَى / فَوْقَ : Üstünde</text>\n  <text x="180" y="128" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">تَحْتَ : Altında · أَمَامَ : Önünde</text>\n  <text x="180" y="156" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">خَلْفَ : Arkasında · بِجَانِبِ : Yanında</text>\n  <text x="180" y="184" text-anchor="middle" font-size="13" font-weight="bold" fill="#155e75">يَمِينَ : Sağında · يَسَارَ : Solunda</text>\n  <text x="180" y="214" text-anchor="middle" font-size="11" fill="#0f172a">Kendinden sonra gelen ismi kesralı (esreli) okutur.</text>\n\n  <rect x="365" y="48" width="310" height="190" rx="8" fill="#fff7ed" stroke="#f97316" stroke-width="1.5"/>\n  <text x="520" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#c2410c">«أَيْنَ ...؟» (Nerede?) Örnek Cümleleri</text>\n  <text x="520" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">أَيْنَ الْحَاسُوبُ؟ ➔ اَلْحَاسُوبُ عَلَى الطَّاوِلَةِ.</text>\n  <text x="520" y="120" text-anchor="middle" font-size="11" fill="#475569">(Bilgisayar nerede? ➔ Bilgisayar masanın üstündedir.)</text>\n  <text x="520" y="148" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">أَيْنَ السَّجَّادَةُ؟ ➔ اَلسَّجَّادَةُ تَحْتَ الطَّاوِلَةِ.</text>\n  <text x="520" y="166" text-anchor="middle" font-size="11" fill="#475569">(Halı nerede? ➔ Halı masanın altındadır.)</text>\n  <text x="520" y="194" text-anchor="middle" font-size="12" font-weight="bold" fill="#9a3412">أَيْنَ الْحَدِيقَةُ؟ ➔ اَلْحَدِيقَةُ أَمَامَ الْبَيْتِ.</text>\n  <text x="520" y="212" text-anchor="middle" font-size="11" fill="#475569">(Bahçe nerede? ➔ Bahçe evin önündedir.)</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
